-- Compare semantics and names, never OIDs or credential material.
SELECT 'functions|' || md5(coalesce(string_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),pg_get_functiondef(p.oid),p.prosecdef,p.proleakproof,p.provolatile,p.proparallel,p.proisstrict,p.proretset,p.procost,p.prorows,p.proconfig,pg_get_userbyid(p.proowner),(SELECT array_agg(x ORDER BY x) FROM unnest(coalesce(p.proacl,acldefault('f',p.proowner))::text[]) x))::text,E'\n' ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),''))
FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind<>'a' AND n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema';
SELECT 'defaults|' || md5(coalesce(string_agg(jsonb_build_array(pg_get_userbyid(d.defaclrole),coalesce(n.nspname,''),d.defaclobjtype,(SELECT array_agg(x ORDER BY x) FROM unnest(d.defaclacl::text[]) x))::text,E'\n' ORDER BY pg_get_userbyid(d.defaclrole),n.nspname,d.defaclobjtype),'')) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace;
SELECT 'column-properties|' || md5(coalesce(string_agg(jsonb_build_array(n.nspname,c.relname,a.attname,a.attidentity,a.attgenerated,a.attstorage,a.attcompression,a.attstattarget,a.attoptions,(SELECT array_agg(x ORDER BY x) FROM unnest(a.attacl::text[]) x),co.collname)::text,E'\n' ORDER BY n.nspname,c.relname,a.attnum),'')) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_collation co ON co.oid=a.attcollation WHERE a.attnum>0 AND NOT a.attisdropped AND n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema';
SELECT 'views-options|' || md5(coalesce(string_agg(jsonb_build_array(n.nspname,c.relname,c.reloptions,CASE WHEN c.relkind IN ('v','m') THEN pg_get_viewdef(c.oid) ELSE NULL END)::text,E'\n' ORDER BY n.nspname,c.relname),'')) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema';
SELECT 'enums|' || md5(coalesce(string_agg(n.nspname||'.'||t.typname||':'||e.enumlabel,E'\n' ORDER BY n.nspname,t.typname,e.enumsortorder),'')) FROM pg_enum e JOIN pg_type t ON t.oid=e.enumtypid JOIN pg_namespace n ON n.oid=t.typnamespace;
SELECT 'roles|' || md5(coalesce(string_agg(jsonb_build_array(rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls,rolconnlimit,rolconfig)::text,E'\n' ORDER BY rolname),'')) FROM pg_roles;
SELECT 'memberships|' || md5(coalesce(string_agg(jsonb_build_array(pg_get_userbyid(roleid),pg_get_userbyid(member),pg_get_userbyid(grantor),admin_option,inherit_option,set_option)::text,E'\n' ORDER BY pg_get_userbyid(roleid),pg_get_userbyid(member),pg_get_userbyid(grantor)),'')) FROM pg_auth_members;
SELECT 'event-triggers|' || md5(coalesce(string_agg(jsonb_build_array(e.evtname,e.evtevent,e.evtenabled,e.evttags,pg_get_userbyid(e.evtowner),n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))::text,E'\n' ORDER BY e.evtname),'')) FROM pg_event_trigger e JOIN pg_proc p ON p.oid=e.evtfoid JOIN pg_namespace n ON n.oid=p.pronamespace;
SELECT 'index-properties|' || md5(coalesce(string_agg(jsonb_build_array(n.nspname,c.relname,i.indisunique,i.indisprimary,i.indisexclusion,i.indimmediate,i.indisvalid,i.indisready,i.indislive,i.indisreplident)::text,E'\n' ORDER BY n.nspname,c.relname),'')) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema';
SELECT 'type-ownership|' || md5(coalesce(string_agg(jsonb_build_array(n.nspname,t.typname,t.typtype,pg_get_userbyid(t.typowner),(SELECT array_agg(x ORDER BY x) FROM unnest(coalesce(t.typacl,acldefault('T',t.typowner))::text[]) x))::text,E'\n' ORDER BY n.nspname,t.typname),'')) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema';
